<script setup lang="ts">
import { ArrowLeft, CalendarClock, Send } from '@lucide/vue'
import { SALON_TIMEZONE,formatXof } from '~~/shared/constants/business'
definePageMeta({middleware:'customer'})
type DetailService={name:string;priceXof:number;durationMinutes:number}
type OpenRequest={type:string;status:string}
type DetailAppointment={reference:string;status:string;startsAt:string;endsAt:string;totalXof:number;depositDueXof:number;amountPaidXof:number;remainingXof:number;services:DetailService[];staffName:string;payments:Array<{status:string;amountXof:number;currency:string}>;requests:OpenRequest[]}
const route=useRoute()
const{data,error,refresh}=await useFetch<{appointment:DetailAppointment}>(`/api/account/appointments/${encodeURIComponent(String(route.params.id))}`,{key:`account-appointment-${route.params.id}`})
const type=ref<'cancel'|'reschedule'>('reschedule'),requestedFor=ref(''),message=ref(''),busy=ref(false),result=ref(''),failure=ref('')
const appointment=computed(()=>data.value?.appointment)
function serviceNames(items:DetailService[]){return items.map((item)=>item.name).join(' · ')}
function serviceDuration(items:DetailService[]){return items.reduce((sum:number,item)=>sum+item.durationMinutes,0)}
function hasOpenRequest(items:OpenRequest[]){return items.some((item)=>item.status==='open')}
async function sendRequest(){busy.value=true;result.value='';failure.value='';try{const body={type:type.value,...(requestedFor.value?{requestedFor:new Date(requestedFor.value).toISOString()}:{}),message:message.value};const response=await $fetch<{message:string}>(`/api/account/appointments/${encodeURIComponent(String(route.params.id))}/request`,{method:'POST',body});result.value=response.message;await refresh()}catch(error){failure.value=(error as{data?:{statusMessage?:string}})?.data?.statusMessage||'La demande n’a pas pu être envoyée.'}finally{busy.value=false}}
function date(value:string){return new Intl.DateTimeFormat('fr-BJ',{timeZone:SALON_TIMEZONE,dateStyle:'full',timeStyle:'short'}).format(new Date(value))}
useSeoMeta({title:'Détail du rendez-vous — Mon compte',robots:'noindex,nofollow'})
</script>
<template><div class="container-narrow detail-page"><NuxtLink class="back-link" to="/mon-compte/rendez-vous"><ArrowLeft :size="14"/> Mes rendez-vous</NuxtLink><div v-if="error" class="empty-state">Rendez-vous introuvable ou accès non autorisé.</div><article v-else-if="appointment" class="surface-card visit-detail"><span class="eyebrow">Référence {{appointment.reference}}</span><h1 class="display">Votre rendez-vous.</h1><p class="visit-date">{{date(appointment.startsAt)}}</p><p><strong>{{serviceNames(appointment.services)}}</strong></p><p>Avec {{appointment.staffName}} · {{serviceDuration(appointment.services)}} min</p><div class="money-row"><span>Total</span><strong>{{formatXof(appointment.totalXof)}}</strong></div><div class="money-row"><span>Acompte reçu</span><strong>{{formatXof(appointment.amountPaidXof)}}</strong></div><div class="money-row"><span>Solde estimé</span><strong>{{formatXof(appointment.remainingXof)}}</strong></div><span class="status-pill">{{appointment.status}}</span><section class="request-box"><h2 class="display">Un changement à demander&nbsp;?</h2><p>Votre rendez-vous ne changera pas avant la confirmation de l’équipe.</p><form @submit.prevent="sendRequest"><label class="form-field"><span>Type de demande</span><select v-model="type" class="form-control"><option value="reschedule">Demander un report</option><option value="cancel">Demander une annulation</option></select></label><label v-if="type==='reschedule'" class="form-field"><span>Date et heure souhaitées (heure du Bénin)</span><input v-model="requestedFor" class="form-control" type="datetime-local" required></label><label class="form-field"><span>Message (facultatif)</span><textarea v-model="message" class="form-control" rows="3" maxlength="800"/></label><button class="btn btn-primary" type="submit" :disabled="busy||appointment.status!=='confirmed'||hasOpenRequest(appointment.requests)">{{busy?'Envoi…':'Envoyer ma demande'}} <Send :size="15"/></button><p v-if="result" class="success" role="status">{{result}}</p><p v-if="failure" class="error" role="alert">{{failure}}</p></form></section><p v-if="hasOpenRequest(appointment.requests)" class="pending-note"><CalendarClock :size="15"/> Une demande est déjà en attente.</p></article></div></template>
<style scoped>.detail-page{padding:4rem 0}.back-link{display:inline-flex;gap:.4rem;margin-bottom:1rem;color:var(--muted);font-size:.68rem}.visit-detail{padding:clamp(1.5rem,5vw,3rem)}.visit-detail h1{margin:.8rem 0;font-size:clamp(3rem,6vw,5rem)}.visit-detail p{color:var(--muted);font-size:.78rem}.visit-date{color:var(--merlot)!important}.money-row{display:flex;justify-content:space-between;border-top:1px solid var(--line);padding:.75rem 0;font-size:.75rem}.request-box{border-top:1px solid var(--line);margin-top:2rem;padding-top:1.5rem}.request-box h2{margin:.4rem 0;font-size:2.7rem}.request-box form{display:grid;gap:1rem;margin-top:1rem}.form-field{display:grid;gap:.4rem}.form-field span{font-size:.7rem;font-weight:700}.error{color:#943d48}.success{color:#2f674c}.pending-note{display:flex;gap:.45rem;align-items:center}</style>
